// Read-modify-write a JSON list with optimistic concurrency.
const cur = await anna.storage.get({ key: "notes/log" });
const log = cur.exists ? cur.value : [];   // ← branch on `exists`, NOT `value`
log.push({ ts: Date.now(), text: "hi" });

try {
  await anna.storage.set({
    key: "notes/log",
    value: log,
    if_match: cur.etag,                    // 412 if someone else wrote first
  });
} catch (e) {
  if (e.code === "precondition_failed") {
    // Someone raced us — refetch and retry.
  }
}

// Write a short-lived OAuth nonce. Bytes are reclaimed automatically.
await anna.storage.set({
  key: "oauth/state/discord",
  value: { nonce: crypto.randomUUID(), created_at: Date.now() },
  ttl_seconds: 600,                  // 10 minutes
  metadata: { provider: "discord" }, // round-trips on `list`
  tags: ["oauth", "ephemeral"],
});

// Optimistic update: read → patch → write with if_match.
async function appendNote(text) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const cur = await anna.storage.get({ key: "notes/log" });
    const next = cur.exists ? [...cur.value, text] : [text];
    try {
      return await anna.storage.set({
        key: "notes/log",
        value: next,
        if_match: cur.etag,           // omit on first insert
      });
    } catch (e) {
      if (e.code !== "precondition_failed") throw e;
      // retry — someone else wrote between get & set
    }
  }
  throw new Error("contended write — gave up after 3 attempts");
}

// Remove a transient OAuth nonce once the callback completes.
try {
  await anna.storage.delete({ key: "oauth/state/discord" });
} catch (e) {
  if (e.code !== "not_found") throw e;   // already gone — fine
}

// Page through every note in this App's bucket.
async function* iterateNotes() {
  let cursor = undefined;
  do {
    const { items, next_cursor } = await anna.storage.list({
      prefix: "notes/",
      limit: 200,
      cursor,
    });
    for (const it of items) yield it;
    cursor = next_cursor ?? undefined;
  } while (cursor);
}

for await (const head of iterateNotes()) {
  console.log(head.key, head.size_bytes, head.tags);
  // call anna.storage.get({ key: head.key }) only if you need the value.
}
